function firstObject(value, fields) {
  if (!value || typeof value !== "object") return null;
  for (const field of fields) {
    const child = value[field];
    if (child && typeof child === "object" && !Array.isArray(child)) return child;
    if (Array.isArray(child)) {
      const object = child.find((item) => item && typeof item === "object" && !Array.isArray(item));
      if (object) return object;
    }
  }
  return null;
}

function mergeHttpAdapterArtifactSources(parent, child) {
  if (!parent || typeof parent !== "object" || Array.isArray(parent)) return child ?? null;
  if (!child || typeof child !== "object" || Array.isArray(child)) return parent;
  return { ...parent, ...child };
}

function firstHttpAdapterArtifactDetailObject(value, depth = 0) {
  if (!value || typeof value !== "object" || depth > 3) return null;
  if (Array.isArray(value)) {
    for (const item of value) {
      const found = firstHttpAdapterArtifactDetailObject(item, depth + 1);
      if (found) return found;
    }
    return null;
  }
  if (hasHttpAdapterArtifactReference(value)) return value;
  for (const field of [
    "artifact",
    "artifacts",
    "file",
    "files",
    "audio",
    "audios",
    "speech",
    "speeches",
    "voice_audio",
    "voiceAudio",
    "subtitle",
    "subtitles",
    "cue",
    "cues",
    "motion",
    "motions",
    "result",
    "output",
    "data",
    "response",
    "results",
    "outputs",
    "items",
  ]) {
    const found = firstHttpAdapterArtifactDetailObject(value[field], depth + 1);
    if (found) return found;
  }
  return null;
}

