function sanitizeHttpAdapterResponse(value, depth = 0) {
  if (value === TEXT_RESPONSE) {
    return {
      response_kind: "text",
      omitted: true,
    };
  }
  if (value === null || value === undefined) return null;
  if (typeof value === "string") return safePublicResponseText(value, "[redacted]", 500);
  if (typeof value === "number" || typeof value === "boolean") return value;
  if (depth >= 4) return "[truncated]";
  if (Array.isArray(value)) {
    return value.slice(0, 20).map((item) => sanitizeHttpAdapterResponse(item, depth + 1));
  }
  if (typeof value === "object") {
    return Object.fromEntries(
      Object.entries(value)
        .slice(0, 40)
        .map(([field, child]) => [field, sanitizeHttpAdapterResponse(child, depth + 1)])
    );
  }
  return safeText(value, 160);
}

function safeText(value, maxLength = 160) {
  return String(value ?? "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, maxLength);
}

function safePublicResponseText(value, fallback, maxLength = 160) {
  const text = safeText(value, maxLength);
  if (!text) return fallback;
  if (UNSAFE_RESPONSE_SUMMARY_PATTERN.test(text)) return fallback;
  return text;
}

function safeArtifactReference(value) {
  const text = safeText(value, 500);
  if (!text) return "";
  if (UNSAFE_RESPONSE_SUMMARY_PATTERN.test(text) && !isAllowedLocalArtifactUrl(text)) {
    return "";
  }
  if (text.startsWith("artifact://")) return text;
  if (/^[a-z0-9_-]+\/[a-z0-9_.-]+$/iu.test(text)) return `artifact://${text}`;
  if (/^\/event-render-manifests\/[a-z0-9_./?=&-]+$/iu.test(text)) return text;
  if (isAllowedLocalArtifactUrl(text)) return text;
  return "";
}

function isAllowedLocalArtifactUrl(value) {
  try {
    const url = new URL(value);
    if (url.protocol !== "http:" && url.protocol !== "https:") return false;
    return ["127.0.0.1", "localhost", "::1", "[::1]"].includes(url.hostname);
  } catch {
    return false;
  }
}

function safeOptionalNumber(value) {
  const number = Number(value);
  if (!Number.isFinite(number)) return null;
  return Number(number.toFixed(4));
}

function safeDurationMs(msValue, secondsValue) {
  const milliseconds = safeOptionalNumber(msValue);
  if (milliseconds !== null) return milliseconds;
  const seconds = safeOptionalNumber(secondsValue);
  return seconds !== null ? Number((seconds * 1000).toFixed(4)) : null;
}

function classifyRequestError(error) {
  if (error?.name === "AbortError") return "timeout";
  return "network_failure";
}

function safeErrorKind(value) {
  const kind = String(value ?? "");
  if (
    [
      "http_status",
      "timeout",
      "network_failure",
      "request_error",
      "invalid_json_response",
      "local_endpoint_policy_blocked",
    ].includes(kind)
  ) {
    return kind;
  }
  return "request_error";
}

function clampInteger(value, min, max, fallback) {
  const number = Number(value);
  if (!Number.isFinite(number)) return fallback;
  return Math.max(min, Math.min(max, Math.trunc(number)));
}

function assertNoForbiddenHttpAdapterResponseFields(value, context, path = "root") {
  if (!value || typeof value !== "object") return;
  if (Array.isArray(value)) {
    value.forEach((item, index) =>
      assertNoForbiddenHttpAdapterResponseFields(item, context, `${path}[${index}]`)
    );
    return;
  }
  for (const [field, child] of Object.entries(value)) {
    if (
      FORBIDDEN_HTTP_ADAPTER_RESPONSE_FIELDS.has(field) &&
      !isAllowedArtifactResponseUrlField(field, path)
    ) {
      throw new ContractError(
        `${context}: response must not echo candidates, commands, commits, or canonical fields`,
        { field, path }
      );
    }
    if (field === "schema" && FORBIDDEN_HTTP_ADAPTER_RESPONSE_SCHEMA_VALUES.has(child)) {
      throw new ContractError(`${context}: response must not echo runtime schemas`, {
        schema: child,
        path,
      });
    }
    assertNoForbiddenHttpAdapterResponseFields(child, context, `${path}.${field}`);
  }
}

function isAllowedArtifactResponseUrlField(field, path) {
  if (field !== "url") return false;
  const parent = String(path ?? "").split(".").at(-1);
  return [
    "artifact",
    "file",
    "audio",
    "speech",
    "voice_audio",
    "voiceAudio",
    "subtitle",
    "cue",
    "motion",
  ].includes(parent);
}
